head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst75000";
scwin.xmlHttp = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst75000.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "cal_date", fn: function () { return String(String((dma_pageContext.get("selDate") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.fnGetHolidayYn();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst75000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst75000.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name btn_fnGetHolidayYn_onclick
 * @description btn_fnGetHolidayYn 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnGetHolidayYn_onclick = async function(e){
    try {
        await scwin.fnGetHolidayYn(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst75000.btn_fnGetHolidayYn_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownload_onclick
 * @description btn_fnDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownload_onclick = async function(e){
    try {
        await scwin.fnDownload(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst75000.btn_fnDownload_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/corpgeneral/listedIssueStatus.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/corpgeneral/listedIssueStatus.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnGetHolidayYn_rawxhr
 * @description fn Get Holiday Yn rawxhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnGetHolidayYn_rawxhr = async function () {
    const sbmOptions = {
        id: "tx_fnGetHolidayYn_rawxhr",
        method: "get",
        action: "/corpgeneral/listedIssueStatus.do?method=getHolidayYn&selDate=",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name fnGetHolidayYnCallback
 * @description fn Get Holiday Yn Callback 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnGetHolidayYnCallback = async function () {
    await scwin.fnSearch();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name createXMLHttpRequest
 * @description create XMLHttp Request 처리
 * @returns {void}
 * @hidden N
 */
scwin.createXMLHttpRequest = function () {
    let xmlHttp = null;
    if (XMLHttpRequest) {
        xmlHttp = new XMLHttpRequest();
    }
    return xmlHttp;
};

/**
 * @method
 * @name fnGetHolidayYn
 * @description fn Get Holiday Yn 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnGetHolidayYn = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_date').getValue())) {
        await $c.win.alert("Date that you inserted is incorrect. Please check the date.");
        return;
    }
    let date = $c.util.getComponent('cal_date').getValue();
    date = date.replace(/\-/g, '');
    await scwin.tx_fnGetHolidayYn_rawxhr();
};

/**
 * @method
 * @name fnCheckHolidayYn
 * @description fn Check Holiday Yn 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnCheckHolidayYn = function () {
    const responseXML = scwin.xmlHttp.responseXML;
    const element = responseXML;
    const nodeList = element.getElementsByTagName("item");
    const node = nodeList[0];
    const value = node.getElementsByTagName("value")[0].firstChild.nodeValue;
    return value;
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("method", "readListedIssueStatus");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "listedIssueStatus");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_date').getValue())) {
        await $c.win.alert("Date that you inserted is incorrect. Please check the date.");
        return;
    }
    $("#searchForm").attr('onsubmit', '');
    $c.util.getComponent("dma_fnDownloadReq").set("method", "readListedIssueStatus");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "excelDownload");
    await scwin.tx_fnDownload();
    $("#searchForm").attr('onsubmit', 'return false;');
};
